      pad0: 0,
      pad1: 0,
      pad2: 0,
      pad3: 0,
      pad4: 0,
      pad5: 0,
      inner: zero_trio()
    }
  end

  @doc """
  Packs a TrioStraddle into a fresh binary and returns the wire bytes. The
  writer trusts the caller up to the O(1) contract checks, which raise
  ArgumentError — always on, since the BEAM has no compile-out assert.
  """
  @spec write_trio_straddle!(Example.TrioStraddle.t()) :: binary()
  def write_trio_straddle!(value) do
    %{
      pad0: value_pad0,
      pad1: value_pad1,
      pad2: value_pad2,
      pad3: value_pad3,
      pad4: value_pad4,
      pad5: value_pad5,
      inner: value_inner
    } = value

    v = value_pad0 &&& 0xFFFFFFFF
    scratch = v
    v = value_pad0 >>> 32 &&& 0xFFFFFFFF
    sc0 = scratch
    scratch = v
    v = value_pad1 &&& 0xFFFFFFFF
    sc1 = scratch
    scratch = v
    v = value_pad1 >>> 32 &&& 0xFFFFFFFF
    sc2 = scratch
    scratch = v
    v = value_pad2 &&& 0xFFFFFFFF
    sc3 = scratch
    scratch = v
    v = value_pad2 >>> 32 &&& 0xFFFFFFFF
    sc4 = scratch
    scratch = v
    v = value_pad3 &&& 0xFFFFFFFF
    sc5 = scratch
    scratch = v
    v = value_pad3 >>> 32 &&& 0xFFFFFFFF
    sc6 = scratch
    scratch = v
    v = value_pad4 &&& 0xFFFFFFFF
    sc7 = scratch
    scratch = v
    v = value_pad4 >>> 32 &&& 0xFFFFFFFF
    sc8 = scratch
    scratch = v
    v = value_pad5 &&& 0xFFFFFF
    sc9 = scratch
    scratch = v
    %{a: value_inner_a, b: value_inner_b, c: value_inner_c} = value_inner
    v = value_inner_a &&& 0xFFFFF
    scratch = scratch ||| v <<< 24
    v = value_inner_b &&& 0xFFFFF
    sc10 = scratch
    scratch = scratch >>> 40
    scratch = scratch ||| v <<< 4
    v = value_inner_c &&& 0xFFFFFF
    scratch = scratch ||| v <<< 24

    <<sc0::little-size(4)-unit(8), sc1::little-size(4)-unit(8), sc2::little-size(4)-unit(8),
      sc3::little-size(4)-unit(8), sc4::little-size(4)-unit(8), sc5::little-size(4)-unit(8),
      sc6::little-size(4)-unit(8), sc7::little-size(4)-unit(8), sc8::little-size(4)-unit(8),
      sc9::little-size(4)-unit(8), sc10::little-size(5)-unit(8), scratch::little-size(6)-unit(8)>>
  end

  @doc """
  write_trio_straddle!/1 as a verdict: `{:ok, binary}`, or `{:error, message}`
  where the bang form raises ArgumentError.
  """
  @spec write_trio_straddle(Example.TrioStraddle.t()) :: {:ok, binary()} | {:error, String.t()}
  def write_trio_straddle(value) do
    {:ok, write_trio_straddle!(value)}
  rescue
    e in ArgumentError -> {:error, Exception.message(e)}
  end

  @doc """
  Decodes a TrioStraddle from the first num_bits of data and REPORTS THE BITS
  CONSUMED (SPEC §5): `{:ok, value, bits_read}`. The count is what frames a
  second object behind the first in one buffer. `:error` rejects the wire
  (bounds, ranges, wire constants, padding); hostile bytes never raise. No
  slack past the payload is required.
  """
  @spec read_trio_straddle_bits(binary(), non_neg_integer()) ::
          {:ok, Example.TrioStraddle.t(), non_neg_integer()} | :error
  def read_trio_straddle_bits(data, num_bits) when is_binary(data) and is_integer(num_bits) do
    try do
      if num_bits > byte_size(data) * 8 do
        # the payload cannot exceed the buffer behind it
        throw(:invalid)
      end

      if 408 > num_bits, do: throw(:invalid)
      rv = rdw(data, 0, 49)
      v = rv &&& 0xFFFFFFFF
      w = v
      rv = rdw(data, 32, 49)
      v = rv &&& 0xFFFFFFFF
      w = w ||| v <<< 32
      v_pad0 = w
      rv = rdw(data, 64, 49)
      v = rv &&& 0xFFFFFFFF
      w = v
      rv = rdw(data, 96, 49)
      v = rv &&& 0xFFFFFFFF
      w = w ||| v <<< 32
      v_pad1 = w
      rv = rdw(data, 128, 49)
      v = rv &&& 0xFFFFFFFF
      w = v
      rv = rdw(data, 160, 49)
      v = rv &&& 0xFFFFFFFF
      w = w ||| v <<< 32
      v_pad2 = w
      rv = rdw(data, 192, 49)
      v = rv &&& 0xFFFFFFFF
      w = v
      rv = rdw(data, 224, 49)
      v = rv &&& 0xFFFFFFFF
      w = w ||| v <<< 32
      v_pad3 = w
      rv = rdw(data, 256, 49)
      v = rv &&& 0xFFFFFFFF
      w = v
      rv = rdw(data, 288, 49)
      v = rv &&& 0xFFFFFFFF
      w = w ||| v <<< 32
      v_pad4 = w
      rv = rdw(data, 320, 49)
      v = rv &&& 0xFFFFFF
      v_pad5 = v
      v = rv >>> 24 &&& 0xFFFFF
      v_inner_a = v
      rv = rdw(data, 364, 44)
      v = rv &&& 0xFFFFF
      v_inner_b = v
      v = rv >>> 20
      v_inner_c = v
      v_inner = %Example.Trio{a: v_inner_a, b: v_inner_b, c: v_inner_c}

      value = %Example.TrioStraddle{
        pad0: v_pad0,
        pad1: v_pad1,
        pad2: v_pad2,
        pad3: v_pad3,
        pad4: v_pad4,
        pad5: v_pad5,
        inner: v_inner
      }

      {:ok, value, 408}
    catch
      :invalid -> :error
    end
  end

  @doc """
  Decodes a TrioStraddle from the first num_bits of data: read_trio_straddle_bits/2
  with the count dropped, the family read verdict.
  """
  @spec read_trio_straddle(binary(), non_neg_integer()) ::
          {:ok, Example.TrioStraddle.t()} | :error
  def read_trio_straddle(data, num_bits) when is_binary(data) and is_integer(num_bits) do
    case read_trio_straddle_bits(data, num_bits) do
      {:ok, value, _bits_read} -> {:ok, value}
      :error -> :error
    end
  end

  defp w_span_f64_values([], data, scratch, scratch_bits), do: {data, scratch, scratch_bits}

  defp w_span_f64_values([e | rest], data, scratch, scratch_bits) do
    w = f64_bits(e)
    v = w &&& 0xFFFFFFFF
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 32
    v = w >>> 32
    sc0 = scratch
    fl0 = scratch_bits >>> 3
    scratch = scratch >>> (fl0 <<< 3)
    scratch_bits = scratch_bits &&& 7
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 32
    flush = scratch_bits >>> 3
    data = <<data::binary, sc0::little-size(fl0)-unit(8), scratch::little-size(flush)-unit(8)>>
    scratch = scratch >>> (flush <<< 3)
    scratch_bits = scratch_bits &&& 7
    w_span_f64_values(rest, data, scratch, scratch_bits)
  end

  defp r_span_f64_values(0, acc, _data, _num_bits, bits_read), do: {bits_read, Enum.reverse(acc)}

  defp r_span_f64_values(remaining, acc, data, num_bits, bits_read) do
    rv = rdw(data, bits_read, 49)
    v = rv &&& 0xFFFFFFFF
    w = v
    rv = rd(data, bits_read + 32, 32)
    v = rv
    w = w ||| v <<< 32
    e = f64_value(w)
    r_span_f64_values(remaining - 1, [e | acc], data, num_bits, bits_read + 64)
  end

  defp w_span_u64_values([], data, scratch, scratch_bits), do: {data, scratch, scratch_bits}

  defp w_span_u64_values([e | rest], data, scratch, scratch_bits) do
    v = e &&& 0xFFFFFFFF
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 32
    v = e >>> 32 &&& 0xFFFFFFFF
    sc0 = scratch
    fl0 = scratch_bits >>> 3
    scratch = scratch >>> (fl0 <<< 3)
    scratch_bits = scratch_bits &&& 7
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 32
    flush = scratch_bits >>> 3
    data = <<data::binary, sc0::little-size(fl0)-unit(8), scratch::little-size(flush)-unit(8)>>
    scratch = scratch >>> (flush <<< 3)
    scratch_bits = scratch_bits &&& 7
    w_span_u64_values(rest, data, scratch, scratch_bits)
  end

  defp r_span_u64_values(0, acc, _data, _num_bits, bits_read), do: {bits_read, Enum.reverse(acc)}

  defp r_span_u64_values(remaining, acc, data, num_bits, bits_read) do
    rv = rdw(data, bits_read, 49)
    v = rv &&& 0xFFFFFFFF
    w = v
    rv = rd(data, bits_read + 32, 32)
    v = rv
    w = w ||| v <<< 32
    e = w
    r_span_u64_values(remaining - 1, [e | acc], data, num_bits, bits_read + 64)
  end

  defp w_span_i64_values([], data, scratch, scratch_bits), do: {data, scratch, scratch_bits}

  defp w_span_i64_values([e | rest], data, scratch, scratch_bits) do
    v = e &&& 0xFFFFFFFF
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 32
    v = e >>> 32 &&& 0xFFFFFFFF
    sc0 = scratch
    fl0 = scratch_bits >>> 3
    scratch = scratch >>> (fl0 <<< 3)
    scratch_bits = scratch_bits &&& 7
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 32
    flush = scratch_bits >>> 3
    data = <<data::binary, sc0::little-size(fl0)-unit(8), scratch::little-size(flush)-unit(8)>>
    scratch = scratch >>> (flush <<< 3)
    scratch_bits = scratch_bits &&& 7
    w_span_i64_values(rest, data, scratch, scratch_bits)
  end

  defp r_span_i64_values(0, acc, _data, _num_bits, bits_read), do: {bits_read, Enum.reverse(acc)}

  defp r_span_i64_values(remaining, acc, data, num_bits, bits_read) do
    rv = rdw(data, bits_read, 49)
    v = rv &&& 0xFFFFFFFF
    w = v
    rv = rd(data, bits_read + 32, 32)
    v = rv
    w = w ||| v <<< 32
    e = if w >= 9_223_372_036_854_775_808, do: w - 18_446_744_073_709_551_616, else: w
    r_span_i64_values(remaining - 1, [e | acc], data, num_bits, bits_read + 64)
  end

  defp w_span_one_values([], data, scratch, scratch_bits), do: {data, scratch, scratch_bits}

  defp w_span_one_values([e | rest], data, scratch, scratch_bits) do
    v = e &&& 0xFFFFFFFF
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 32
    v = e >>> 32 &&& 0xFFFFFFFF
    sc0 = scratch
    fl0 = scratch_bits >>> 3
    scratch = scratch >>> (fl0 <<< 3)
    scratch_bits = scratch_bits &&& 7
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 32
    flush = scratch_bits >>> 3
    data = <<data::binary, sc0::little-size(fl0)-unit(8), scratch::little-size(flush)-unit(8)>>
    scratch = scratch >>> (flush <<< 3)
    scratch_bits = scratch_bits &&& 7
    w_span_one_values(rest, data, scratch, scratch_bits)
  end

  defp r_span_one_values(0, acc, _data, _num_bits, bits_read), do: {bits_read, Enum.reverse(acc)}

  defp r_span_one_values(remaining, acc, data, num_bits, bits_read) do
    rv = rdw(data, bits_read, 49)
    v = rv &&& 0xFFFFFFFF
    w = v
    rv = rd(data, bits_read + 32, 32)
    v = rv
    w = w ||| v <<< 32
    e = w
    r_span_one_values(remaining - 1, [e | acc], data, num_bits, bits_read + 64)
  end

  defp w_span_chunk_values([], data, scratch, scratch_bits), do: {data, scratch, scratch_bits}

  defp w_span_chunk_values([e1, e2, e3, e4 | rest], data, scratch, scratch_bits) do
    v = e1 &&& 0xFFFF
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 16
    v = e2 &&& 0xFFFF
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 16
    v = e3 &&& 0xFFFF
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 16
    v = e4 &&& 0xFFFF
    sc0 = scratch
    fl0 = scratch_bits >>> 3
    scratch = scratch >>> (fl0 <<< 3)
    scratch_bits = scratch_bits &&& 7
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 16
    flush = scratch_bits >>> 3
    data = <<data::binary, sc0::little-size(fl0)-unit(8), scratch::little-size(flush)-unit(8)>>
    scratch = scratch >>> (flush <<< 3)
    scratch_bits = scratch_bits &&& 7
    w_span_chunk_values(rest, data, scratch, scratch_bits)
  end

  defp w_span_chunk_values([e | rest], data, scratch, scratch_bits) do
    v = e &&& 0xFFFF
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 16
    flush = scratch_bits >>> 3
    data = <<data::binary, scratch::little-size(flush)-unit(8)>>
    scratch = scratch >>> (flush <<< 3)
    scratch_bits = scratch_bits &&& 7
    w_span_chunk_values(rest, data, scratch, scratch_bits)
  end

  defp r_span_chunk_values(0, acc, _data, _num_bits, bits_read),
    do: {bits_read, Enum.reverse(acc)}

  defp r_span_chunk_values(remaining, acc, data, num_bits, bits_read)
       when remaining >= 3 do
    rv = rdw(data, bits_read, 48)
    v = rv &&& 0xFFFF
    e1 = v
    v = rv >>> 16 &&& 0xFFFF
    e2 = v
    v = rv >>> 32
    e3 = v
    r_span_chunk_values(remaining - 3, [e3, e2, e1 | acc], data, num_bits, bits_read + 48)
  end

  defp r_span_chunk_values(remaining, acc, data, num_bits, bits_read) do
    rv = rd(data, bits_read, 16)
    v = rv
    e = v
    r_span_chunk_values(remaining - 1, [e | acc], data, num_bits, bits_read + 16)
  end

  defp r_span_chunk_values_align(remaining, acc, data, num_bits, bits_read)
       when remaining >= 4 do
    i = bits_read >>> 3
    q = bits_read &&& 7

    if q == 0 do
      case data do
        <<_::binary-size(^i), rest::binary>> ->
          r_span_chunk_values_fast(remaining, acc, data, num_bits, bits_read, rest, 0, 0)

        _ ->
          r_span_chunk_values(remaining, acc, data, num_bits, bits_read)
      end
    else
      case data do
        <<_::binary-size(^i), b0, rest::binary>> ->
          r_span_chunk_values_fast(
            remaining,
            acc,
            data,
            num_bits,
            bits_read,
            rest,
            b0 >>> q,
            8 - q
          )

        _ ->
          r_span_chunk_values(remaining, acc, data, num_bits, bits_read)
      end
    end
  end

  defp r_span_chunk_values_align(remaining, acc, data, num_bits, bits_read),
    do: r_span_chunk_values(remaining, acc, data, num_bits, bits_read)

  defp r_span_chunk_values_fast(
         remaining,
         acc,
         data,
         num_bits,
         bits_read,
         <<s1::little-40, s2::little-24, rest::binary>>,
         carry,
         c
       )
       when remaining >= 4 do
    z1 = carry ||| s1 <<< c
    v = z1 &&& 0xFFFF
    e1 = v
    v = z1 >>> 16 &&& 0xFFFF
    e2 = v
    z2 = z1 >>> 32 ||| s2 <<< (c + 8)
    v = z2 &&& 0xFFFF
    e3 = v
    v = z2 >>> 16 &&& 0xFFFF
    e4 = v

    {bits_read, tail} =
      r_span_chunk_values_fast(
        remaining - 4,
        acc,
        data,
        num_bits,
        bits_read + 64,
        rest,
        z2 >>> 32,
        c
      )

    {bits_read, [e1, e2, e3, e4 | tail]}
  end

  defp r_span_chunk_values_fast(remaining, acc, data, num_bits, bits_read, _rest, _carry, _c),
    do: r_span_chunk_values(remaining, acc, data, num_bits, bits_read)

  defp w_span_tail_values([], data, scratch, scratch_bits), do: {data, scratch, scratch_bits}

  defp w_span_tail_values([e | rest], data, scratch, scratch_bits) do
    w = f64_bits(e)
    v = w &&& 0xFFFFFFFF
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 32
    v = w >>> 32
    sc0 = scratch
    fl0 = scratch_bits >>> 3
    scratch = scratch >>> (fl0 <<< 3)
    scratch_bits = scratch_bits &&& 7
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 32
    flush = scratch_bits >>> 3
    data = <<data::binary, sc0::little-size(fl0)-unit(8), scratch::little-size(flush)-unit(8)>>
    scratch = scratch >>> (flush <<< 3)
    scratch_bits = scratch_bits &&& 7
    w_span_tail_values(rest, data, scratch, scratch_bits)
  end

  defp r_span_tail_values(0, acc, _data, _num_bits, bits_read), do: {bits_read, Enum.reverse(acc)}

  defp r_span_tail_values(remaining, acc, data, num_bits, bits_read) do
    rv = rdw(data, bits_read, 49)
    v = rv &&& 0xFFFFFFFF
    w = v
    rv = rd(data, bits_read + 32, 32)
    v = rv
    w = w ||| v <<< 32
    e = f64_value(w)
    r_span_tail_values(remaining - 1, [e | acc], data, num_bits, bits_read + 64)
  end

  defp w_span_twice_a([], data, scratch, scratch_bits), do: {data, scratch, scratch_bits}

  defp w_span_twice_a([e | rest], data, scratch, scratch_bits) do
    w = f64_bits(e)
    v = w &&& 0xFFFFFFFF
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 32
    v = w >>> 32
    sc0 = scratch
    fl0 = scratch_bits >>> 3
    scratch = scratch >>> (fl0 <<< 3)
    scratch_bits = scratch_bits &&& 7
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 32
    flush = scratch_bits >>> 3
    data = <<data::binary, sc0::little-size(fl0)-unit(8), scratch::little-size(flush)-unit(8)>>
    scratch = scratch >>> (flush <<< 3)
    scratch_bits = scratch_bits &&& 7
    w_span_twice_a(rest, data, scratch, scratch_bits)
  end

  defp w_span_twice_b([], data, scratch, scratch_bits), do: {data, scratch, scratch_bits}

  defp w_span_twice_b([e | rest], data, scratch, scratch_bits) do
    w = f64_bits(e)
    v = w &&& 0xFFFFFFFF
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 32
    v = w >>> 32
    sc0 = scratch
    fl0 = scratch_bits >>> 3
    scratch = scratch >>> (fl0 <<< 3)
    scratch_bits = scratch_bits &&& 7
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 32
    flush = scratch_bits >>> 3
    data = <<data::binary, sc0::little-size(fl0)-unit(8), scratch::little-size(flush)-unit(8)>>
    scratch = scratch >>> (flush <<< 3)
    scratch_bits = scratch_bits &&& 7
    w_span_twice_b(rest, data, scratch, scratch_bits)
  end

  defp r_span_twice_a(0, acc, _data, _num_bits, bits_read), do: {bits_read, Enum.reverse(acc)}

  defp r_span_twice_a(remaining, acc, data, num_bits, bits_read) do
    rv = rdw(data, bits_read, 49)
    v = rv &&& 0xFFFFFFFF
    w = v
    rv = rd(data, bits_read + 32, 32)
    v = rv
    w = w ||| v <<< 32
    e = f64_value(w)
    r_span_twice_a(remaining - 1, [e | acc], data, num_bits, bits_read + 64)
  end

  defp r_span_twice_b(0, acc, _data, _num_bits, bits_read), do: {bits_read, Enum.reverse(acc)}

  defp r_span_twice_b(remaining, acc, data, num_bits, bits_read) do
    rv = rdw(data, bits_read, 49)
    v = rv &&& 0xFFFFFFFF
    w = v
    rv = rd(data, bits_read + 32, 32)
    v = rv
    w = w ||| v <<< 32
    e = f64_value(w)
    r_span_twice_b(remaining - 1, [e | acc], data, num_bits, bits_read + 64)
  end
